#!/usr/bin/env bash
# 5-fold cross-validation CPU resource benchmark.
#
# Runs every CPU method on each subset for folds 0-4, so each cell appears
# exactly once in a test fold.  Per-fold JSONs live in
# results/cpu_5fold/folds/fold{k}/; aggregate mean+-sd JSONs are produced in
# results/cpu_5fold/ by aggregate_5fold.py, and figures are generated by
# generate_figure_5fold.py.
#
# Usage:
#     cd comparison/resource_comparison
#     nohup ./run_benchmark_5fold.sh > benchmark_5fold.log 2>&1 &

set -euo pipefail

# ----------------------------- Configuration ---------------------------------
CONDA_BASE="${HOME}/miniconda3"

COMP_CPU_ENV="compo"        # Compocyte v2_cpu (CPU-only)
SOTA_ENV="scrna"            # scANVI / CellTypist / treeArches / scPoli / figures
RSCRIPT="Rscript"

SUBSETS=("liu_100k" "zhang_250k" "oelen_e1_500k")
FOLDS=(0 1 2 3 4)
N_FOLDS=5

MIN_FREE_GB=20

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# ----------------------------- Output layout ---------------------------------
BASE_OUT="${SCRIPT_DIR}/results/cpu_5fold"
FOLDS_DIR="${BASE_OUT}/folds"
mkdir -p "${BASE_OUT}" "${FOLDS_DIR}"

# ----------------------------- Helpers ---------------------------------------
source_conda() {
    if [ -f "${CONDA_BASE}/etc/profile.d/conda.sh" ]; then
        # shellcheck source=/dev/null
        source "${CONDA_BASE}/etc/profile.d/conda.sh"
    else
        echo "ERROR: conda.sh not found at ${CONDA_BASE}/etc/profile.d/conda.sh" >&2
        exit 1
    fi
}

run_py() {
    local env="$1"
    shift
    source_conda
    conda run -n "$env" python "$@"
}

# ----------------------------- Space check -----------------------------------
FREE_GB=$(df -BG "$SCRIPT_DIR" | awk 'NR==2 {gsub(/G/,"",$4); print $4}')
if [ "$FREE_GB" -lt "$MIN_FREE_GB" ]; then
    echo "ERROR: only ${FREE_GB} GB free; need at least ${MIN_FREE_GB} GB." >&2
    exit 1
fi
echo "Free disk space: ${FREE_GB} GB"

# ----------------------------- Environment checks ----------------------------
echo ""
echo "===== Checking Python environments ====="
source_conda
for env in "$COMP_CPU_ENV" "$SOTA_ENV"; do
    if ! conda info --envs | awk '{print $1}' | grep -qx "$env"; then
        echo "ERROR: conda environment '$env' not found." >&2
        exit 1
    fi
done

conda run -n "$COMP_CPU_ENV" python -c "import Compocyte, torch" 2>/dev/null || {
    echo "ERROR: Compocyte/torch not available in $COMP_CPU_ENV" >&2
    exit 1
}

conda run -n "$SOTA_ENV" python - <<'PY' || { echo "ERROR: SOTA Python packages missing" >&2; exit 1; }
for pkg in ['scanpy','skmisc','scvi','celltypist','scarches','scHPL','networkx','sklearn','matplotlib','pandas','numpy']:
    __import__(pkg)
PY

echo ""
echo "===== Checking R packages ====="
"$RSCRIPT" --vanilla -e '
.libPaths(c("/home/ritwik24222/R/library", .libPaths()))
for (p in c("CHETAH","scuttle","scran","optparse","mclust","Seurat","Matrix","Rtsne","data.table","jsonlite")) {
  if (!requireNamespace(p, quietly=TRUE)) stop(paste(p, "not installed"))
}
cat("R packages OK\n")
' 2>/dev/null || {
    echo "ERROR: required R packages missing." >&2
    exit 1
}

# ----------------------------- 5-fold benchmark run --------------------------
echo ""
echo "===== Starting 5-fold CPU benchmark ====="
START=$(date +%Y-%m-%d\ %H:%M:%S)
echo "Start time: $START"

for subset in "${SUBSETS[@]}"; do
    for fold in "${FOLDS[@]}"; do
        FOLD_OUT="${FOLDS_DIR}/fold${fold}"
        mkdir -p "$FOLD_OUT"

        echo ""
        echo "=== Subset: $subset | Fold: $fold ==="

        echo "  Compocyte v2_cpu ..."
        run_py "$COMP_CPU_ENV" train_compocyte_cpu.py --subset "$subset" --epochs 100 --fold "$fold" --out-dir "$FOLD_OUT" || true

        echo "  scANVI (CPU) ..."
        run_py "$SOTA_ENV" train_scanvi.py --subset "$subset" --epochs 100 --fold "$fold" --out-dir "$FOLD_OUT" || true

        echo "  CellTypist (CPU) ..."
        run_py "$SOTA_ENV" train_celltypist.py --subset "$subset" --fold "$fold" --out-dir "$FOLD_OUT" || true

        echo "  treeArches (CPU) ..."
        run_py "$SOTA_ENV" train_treearches.py --subset "$subset" --epochs 100 --fold "$fold" --out-dir "$FOLD_OUT" || true

        echo "  scPoli (CPU) ..."
        run_py "$SOTA_ENV" train_scpoli.py --subset "$subset" --epochs 100 --fold "$fold" --out-dir "$FOLD_OUT" || true

        echo "  CHETAH ..."
        run_py "$SOTA_ENV" run_chetah.py --subset "$subset" --fold "$fold" --out-dir "$FOLD_OUT" || true

        echo "  transferData ..."
        run_py "$SOTA_ENV" run_transferdata.py --subset "$subset" --fold "$fold" --out-dir "$FOLD_OUT" || true
    done
done

# ----------------------------- Aggregation & figures -------------------------
echo ""
echo "===== Aggregating 5-fold results ====="
run_py "$SOTA_ENV" aggregate_5fold.py \
    --folds-dir "$FOLDS_DIR" \
    --out-dir "$BASE_OUT" \
    --n-folds "$N_FOLDS"

echo ""
echo "===== Generating 5-fold figures ====="
run_py "$SOTA_ENV" generate_figure_5fold.py \
    --results-dir "$BASE_OUT" \
    --out-dir "${SCRIPT_DIR}/figs"

END=$(date +%Y-%m-%d\ %H:%M:%S)
echo ""
echo "===== 5-fold CPU benchmark complete ====="
echo "Start: $START"
echo "End:   $END"
echo "Fold results:  $FOLDS_DIR"
echo "Aggregated:    $BASE_OUT"
echo "Figures:       ${SCRIPT_DIR}/figs"
